package warranty

import (
	"errors"
	"testing"
	"time"
)

func TestTempRegisterPartDuplicateScenarios(t *testing.T) {
	s := NewStore()
	t0 := time.Date(2026, 1, 1, 0, 0, 0, 0, time.UTC)
	if err := s.RegisterProduct("p1", t0, 30, nil); err != nil {
		t.Fatal(err)
	}
	if err := s.RegisterPart("x", 10); err != nil {
		t.Fatal(err)
	}
	if err := s.SubmitRequest("r1", "p1", "F"); err != nil {
		t.Fatal(err)
	}
	expiry := t0.Add(24 * time.Hour)
	if _, err := s.Reserve("c1", "r1", "x", 6, expiry, t0); err != nil {
		t.Fatal(err)
	}
	if _, err := s.Use("u1", "c1", 2, t0); err != nil {
		t.Fatal(err)
	}

	for _, stock := range []int{-1, 0, 20, 10} {
		err := s.RegisterPart("x", stock)
		if !errors.Is(err, ErrDuplicateID) {
			t.Fatalf("re-register with stock %d: got %v, want ErrDuplicateID", stock, err)
		}
		if errors.Is(err, ErrInvalidParam) {
			t.Fatalf("re-register with stock %d matched ErrInvalidParam too", stock)
		}
	}

	p, err := s.Part("x")
	if err != nil || p.Stock != 8 {
		t.Fatalf("part after duplicates: %+v, %v", p, err)
	}
	st, err := s.PartStatus("x", t0)
	if err != nil {
		t.Fatal(err)
	}
	if st.PhysicalRemaining != 8 || st.ActiveOccupied != 4 || st.Committable != 4 {
		t.Fatalf("status after duplicates: %+v", st)
	}
	if len(st.Details) != 1 {
		t.Fatalf("details: %+v", st.Details)
	}
	d := st.Details[0]
	if d.CommitmentID != "c1" || d.OriginalQuantity != 6 || d.UsedQuantity != 2 ||
		d.RemainingQuantity != 4 || !d.Expiry.Equal(expiry) || d.Status != CommitmentActive {
		t.Fatalf("original commitment altered: %+v", d)
	}

	// 首次登记的负库存不占用编号。
	if err := s.RegisterPart("new", -5); !errors.Is(err, ErrInvalidParam) {
		t.Fatalf("negative first stock: got %v", err)
	}
	if _, err := s.Part("new"); !errors.Is(err, ErrNotFound) {
		t.Fatalf("negative first stock occupied the id: %v", err)
	}
	if err := s.RegisterPart("new", 0); err != nil {
		t.Fatalf("zero first registration failed: %v", err)
	}
	if p, err := s.Part("new"); err != nil || p.Stock != 0 {
		t.Fatalf("zero-stock part: %+v, %v", p, err)
	}
	if st, err := s.PartStatus("new", t0); err != nil ||
		st.PhysicalRemaining != 0 || st.ActiveOccupied != 0 || st.Committable != 0 {
		t.Fatalf("zero-stock status: %+v, %v", st, err)
	}
	if err := s.RegisterPart("", 1); !errors.Is(err, ErrInvalidParam) {
		t.Fatalf("empty id: %v", err)
	}
}

